-- VS-477. Captain wants several plans in development at once, shown as tabs, and a per-plan tab
-- title. The one-drafting-plan-per-project rule lived entirely in the partial unique index
-- `plans_one_drafting_per_project` (0041), so dropping it is the whole storage change; every draft,
-- blocker and planner constraint is untouched. `plans.title` existed but was never generated;
-- `title_source` records whether a title was auto-generated by the planner or supplied by captain,
-- so an auto-generated title can never overwrite a title captain renamed (the title itself may be
-- non-null in both cases, which is why a flag is needed rather than inferring from NULL).
DROP INDEX IF EXISTS plans_one_drafting_per_project;

ALTER TABLE plans ADD COLUMN title_source TEXT NOT NULL DEFAULT 'auto' CHECK (title_source IN ('auto', 'human'));

-- A title that predates this column could only have been set at creation by a caller, i.e. by
-- captain; every plan created without one keeps the 'auto' default.
UPDATE plans SET title_source = 'human' WHERE title IS NOT NULL;
